3.3 Writing the page images
prepare_page() in the OCR script (shown in Local OCR) applies the right path for each page: crop for spreads, full-page render for portrait pages and the 1966 journal. The helper that reads page lists such as 1;44-46 from the config is shared by several scripts:


Show code
# Small helpers shared by several steps.
library(tidyverse)

# "1;44-46" -&gt; c(1, 44, 45, 46). Page lists in volume_config.csv use this form.
parse_pages &lt;- function(x) {
  if (is.na(x)) return(integer())
  str_split_1(x, ";") |&gt;
    map(\(s) { r &lt;- as.integer(str_split_1(s, "-")); seq(r[1], r[length(r)]) }) |&gt;
    unlist()
}


Page images are written to data/pages/ and are not committed.

4.4 Code
The tiering, draft text and review images are produced by one script. It reads the cached OCR results, marks flagged words as [?word] in the draft text, and draws red boxes on the page images of tiers A and B for the proofreading app.


Show code
# Aggregate cached OCR into triage tiers, draft text, review images and the
# manual queue. Reads data/interim/ocr/*.rds (see R/ocr_pipeline.R) and the
# per-volume settings in data/volume_config.csv. Returns every file it writes.
library(tidyverse)
library(magick)
source("R/utils.R")

low_conf_cut &lt;- 60   # tesseract word confidence below this is flagged

# Pages the config forces into tier A (front matter, two-column layouts)
forced_pages &lt;- function(config) {
  config |&gt;
    filter(!is.na(force_manual_pages)) |&gt;
    mutate(page = map(force_manual_pages, parse_pages)) |&gt;
    unnest(page) |&gt;
    transmute(page_id = sprintf("%s_p%03d", volume_id, page)) |&gt;
    pull(page_id)
}


# Rebuild lines from word boxes so flagged words can be marked inline
mark_text &lt;- function(w) {
  w &lt;- w |&gt; mutate(ymid = (y0 + y1) / 2, h = y1 - y0)
  lh &lt;- median(w$h)
  w |&gt;
    arrange(ymid, x0) |&gt;
    mutate(line = cumsum(c(TRUE, diff(ymid) &gt; 0.6 * lh))) |&gt;
    arrange(line, x0) |&gt;
    mutate(out = if_else(flagged, paste0("[?", word, "]"), word)) |&gt;
    summarise(.by = line, txt = paste(out, collapse = " ")) |&gt;
    pull(txt) |&gt; paste(collapse = "\n")
}

build_outputs &lt;- function(config, ocr_files = list.files("data/interim/ocr", full.names = TRUE)) {
  forced_manual &lt;- forced_pages(config)
  res &lt;- map(ocr_files, readRDS) |&gt; set_names(tools::file_path_sans_ext(basename(ocr_files)))

  words &lt;- map_dfr(res, "words") |&gt;
    mutate(token = str_replace_all(word, "^[^A-Za-z']+|[^A-Za-z']+$", ""),
           is_word = nchar(token) &gt;= 2)
  bad &lt;- spelling::spell_check_text(paste(unique(words$token[words$is_word]), collapse = "\n"))$word
  words &lt;- words |&gt;
    mutate(low_conf = confidence &lt; low_conf_cut,
           misspelled = is_word & token %in% bad,
           flagged = low_conf | misspelled)

  pages &lt;- words |&gt;
    summarise(.by = page_id, n_words = n(), mean_conf = mean(confidence),
              pct_low = mean(low_conf), pct_flag = mean(flagged)) |&gt;
    mutate(volume = str_sub(page_id, 1, 4), page = as.integer(str_sub(page_id, 7)),
           tier = case_when(page_id %in% forced_manual ~ "A_manual",
                            pct_flag &gt;= 0.25 | n_words &lt; 40 ~ "A_manual",
                            pct_flag &gt;= 0.10 ~ "B_proofread",
                            TRUE ~ "C_spot_check"),
           reason = case_when(page_id %in% forced_manual ~ "front matter or two-column layout",
                              n_words &lt; 40 ~ "very few words (short or failed page)",
                              pct_flag &gt;= 0.25 ~ "high share of low-confidence or non-dictionary words",
                              pct_flag &gt;= 0.10 ~ "moderate share of flagged words")) |&gt;
    arrange(volume, page)

  drafts &lt;- words |&gt; group_split(page_id) |&gt;
    set_names(map_chr(group_split(words, page_id), \(d) d$page_id[1])) |&gt;
    map_chr(mark_text)
  pages &lt;- pages |&gt;
    mutate(text = map_chr(page_id, \(id) str_trim(res[[id]]$text)),
           text_marked = drafts[page_id])

  dir.create("output", showWarnings = FALSE)
  write_csv(select(pages, page_id, volume, page, tier, reason, n_words, mean_conf, pct_low, pct_flag, text, text_marked),
            "output/pages.csv")
  write_csv(select(words, page_id, word, confidence, x0, y0, x1, y1, low_conf, misspelled, flagged),
            "output/ocr_words.csv")

  # Draft text per volume: tier A pages carry a banner, flagged words are [?word]
  draft_files &lt;- map_chr(unique(pages$volume), \(v) {
    pg &lt;- filter(pages, volume == v)
    txt &lt;- pmap_chr(pg, \(page, tier, text_marked, ...) {
      banner &lt;- if (tier == "A_manual") "\n*** MANUAL TRANSCRIPTION NEEDED: OCR unreliable ***" else ""
      sprintf("[p. %d]%s\n%s\n", page, banner, text_marked)
    })
    path &lt;- file.path("output", paste0(v, "_draft.txt"))
    writeLines(txt, path)
    path
  })

  # Review images: red boxes on flagged words, for tier A and B pages
  dir.create("data/pages/review", showWarnings = FALSE, recursive = TRUE)
  review_files &lt;- pages |&gt; filter(tier != "C_spot_check") |&gt; pull(page_id) |&gt; map_chr(\(id) {
    w &lt;- filter(words, page_id == id, flagged)
    img &lt;- image_read(file.path("data/pages", paste0(id, ".png")))
    img &lt;- image_draw(img)
    rect(w$x0 - 2, w$y0 - 2, w$x1 + 2, w$y1 + 2, border = "red", lwd = 2)
    dev.off()
    path &lt;- file.path("data/pages/review", paste0(id, ".png"))
    image_write(image_resize(img, "50%"), path, format = "png")
    path
  })

  # Manual queue: pages ranked by how much work they need
  queue &lt;- pages |&gt;
    filter(tier != "C_spot_check") |&gt;
    mutate(n_flagged = round(pct_flag * n_words)) |&gt;
    arrange(tier, desc(pct_flag)) |&gt;
    select(page_id, tier, reason, n_words, n_flagged, pct_flag, mean_conf)
  write_csv(queue, "output/manual_queue.csv")

  c("output/pages.csv", "output/ocr_words.csv", "output/manual_queue.csv", draft_files, review_files)
}

5.1 Method
Every page is run through Tesseract in its automatic page-segmentation mode (psm 3) on a grayscale image. For each page the script saves the full text and a word table with confidence and bounding box. Results are cached one file per page, so an interrupted run resumes and nothing is recomputed unnecessarily.
Show code
# Page pipeline: PDF page -&gt; cropped 300 DPI PNG -&gt; tesseract OCR -&gt; word table
# and page text, cached per page so a run can be stopped and resumed.
#   data/pages/&lt;page_id&gt;.png        prepared page image
#   data/interim/ocr/&lt;page_id&gt;.rds  list(text, words, langs)
library(tidyverse)
library(pdftools)
library(magick)
library(tesseract)
source("R/utils.R")
source("R/crop_spread.R")

cfg &lt;- read_csv("data/volume_config.csv", show_col_types = FALSE)


page_ids &lt;- function(vol) {
  row &lt;- filter(cfg, volume_id == vol)
  tibble(volume_id = vol, file = row$file, page = seq_len(row$n_pages),
         page_id = sprintf("%s_p%03d", vol, page),
         layout = row$layout, is_portrait = page %in% parse_pages(row$portrait_pages))
}

# Download any tesseract language data that volume_config.csv asks for and is
# not installed. Stops if a language is still missing, so a run never silently
# uses fewer languages than the config says.
ensure_languages &lt;- function(config) {
  want &lt;- config$ocr_langs |&gt; str_split("\\+") |&gt; unlist() |&gt; unique()
  for (lang in setdiff(want, tesseract_info()$available)) {
    message("Downloading tesseract language data: ", lang)
    tesseract_download(lang, progress = FALSE)
  }
  missing &lt;- setdiff(want, tesseract_info()$available)
  if (length(missing)) stop("Tesseract language data still missing: ", paste(missing, collapse = ", "))
  sort(want)
}

prepare_page &lt;- function(vol, page, force = FALSE) {
  id &lt;- sprintf("%s_p%03d", vol, page)
  out &lt;- file.path("data/pages", paste0(id, ".png"))
  if (!force && file.exists(out)) return(out)
  row &lt;- filter(cfg, volume_id == vol)
  pdf &lt;- file.path("data/raw_pdf", row$file)
  img &lt;- if (row$layout == "spread" && !(page %in% parse_pages(row$portrait_pages))) {
    suppressWarnings(crop_text_half(pdf, page))
  } else {
    tmp &lt;- file.path("data/interim", paste0("full_", id, ".png"))
    suppressWarnings(pdf_convert(pdf, pages = page, dpi = 300, format = "png",
                                 filenames = tmp, verbose = FALSE))
    on.exit(unlink(tmp))
    image_read(tmp)
  }
  dir.create(dirname(out), showWarnings = FALSE, recursive = TRUE)
  image_write(img, out, format = "png")
  out
}

ocr_engine &lt;- function(langs = "eng", psm = 3) {
  tesseract(langs, options = list(tessedit_pageseg_mode = as.character(psm)))
}

# A cached result is reused only if it was made with the same languages, so
# changing ocr_langs in the config reruns the affected pages.
ocr_page &lt;- function(vol, page, langs = "eng", force = FALSE) {
  id &lt;- sprintf("%s_p%03d", vol, page)
  cache &lt;- file.path("data/interim/ocr", paste0(id, ".rds"))
  if (!force && file.exists(cache) && identical(readRDS(cache)$langs, langs)) {
    return(invisible(cache))
  }
  png &lt;- prepare_page(vol, page, force = force)
  img &lt;- image_read(png) |&gt; image_convert(colorspace = "gray")
  raw &lt;- image_write(img, format = "png")
  eng &lt;- ocr_engine(langs)
  words &lt;- ocr_data(raw, engine = eng) |&gt;
    mutate(page_id = id, .before = 1) |&gt;
    separate_wider_delim(bbox, ",", names = c("x0", "y0", "x1", "y1")) |&gt;
    mutate(across(x0:y1, as.integer))
  text &lt;- ocr(raw, engine = eng)
  dir.create(dirname(cache), showWarnings = FALSE, recursive = TRUE)
  saveRDS(list(text = text, words = words, langs = langs), cache)
  invisible(cache)
}
The whole set of 378 pages runs in parallel across worker processes. With six workers it takes about 2.6 seconds per page, roughly 20 minutes in total. Pages already in the cache are skipped unless they were made with different languages. Languages come from data/volume_config.csv, and ensure_languages() installs any that are missing before the run starts.
Show code
# Run the page pipeline (prepare_page + ocr_page) for whole volumes in parallel.
# Results are cached per page, so a rerun only processes pages that are missing
# or were made with different languages (force = TRUE redoes everything).
# About 2.6 s/page with 6 workers. Returns the paths of all cached results.
source("R/ocr_pipeline.R")
library(parallel)

run_ocr &lt;- function(config, pdf_files = NULL, workers = 6, force = FALSE) {
  jobs &lt;- map(config$volume_id, \(v) {
    # Languages come straight from the config; ensure_languages() has installed them
    page_ids(v) |&gt; mutate(langs = filter(config, volume_id == v)$ocr_langs)
  }) |&gt; list_rbind()

  cl &lt;- makeCluster(workers)
  on.exit(stopCluster(cl))
  clusterEvalQ(cl, source("R/ocr_pipeline.R"))
  parLapplyLB(cl, seq_len(nrow(jobs)), \(i, jobs, force) {
    ocr_page(jobs$volume_id[i], jobs$page[i], langs = jobs$langs[i], force = force)
  }, jobs = jobs, force = force) |&gt;
    invisible()
  file.path("data/interim/ocr", paste0(jobs$page_id, ".rds"))
}

7.5 Code


Show code
# Launch the proofreading app from the project root.
# Requires output/pages.csv (run R/build_outputs.R first).
run_proofread &lt;- function(root = getwd()) {
  stopifnot(file.exists(file.path(root, "output", "pages.csv")))
  options(pomeroy.root = normalizePath(root))
  shiny::runApp(file.path(root, "proofread"), launch.browser = TRUE)
}

# Apply data/corrections.csv to the OCR text: one final text per page.
# Corrected pages replace the draft; everything else keeps the OCR draft.
# Leftover [?word] marks stay visible so unresolved words are never hidden.
apply_corrections &lt;- function(pages = readr::read_csv("output/pages.csv", show_col_types = FALSE),
                              corr_path = "data/corrections.csv") {
  corr &lt;- if (file.exists(corr_path)) {
    readr::read_csv(corr_path, col_types = "cccc", show_col_types = FALSE)
  } else {
    tibble::tibble(page_id = character(), status = character(),
                   corrected_text = character(), saved_at = character())
  }
  pages |&gt;
    dplyr::left_join(dplyr::select(corr, page_id, status, corrected_text), by = "page_id") |&gt;
    dplyr::mutate(final_text = dplyr::coalesce(corrected_text, text_marked),
                  source = dplyr::coalesce(status, "ocr_draft")) |&gt;
    dplyr::select(-corrected_text, -status)
}


The app itself:


Show code
# Proofreading app: scan image beside editable OCR text.
# Launch with run_proofread() from R/proofread.R (sets the project root).
# Saves to data/corrections.csv, one row per page (latest save wins).
# Edits are auto-saved when you leave a page; pages you only view are not recorded.
library(shiny)
library(bslib)
library(readr)
library(dplyr)
library(stringr)

root &lt;- getOption("pomeroy.root", normalizePath(".."))
corr_path &lt;- file.path(root, "data", "corrections.csv")
addResourcePath("scan", file.path(root, "data", "pages"))
addResourcePath("review", file.path(root, "data", "pages", "review"))

pages &lt;- read_csv(file.path(root, "output", "pages.csv"), show_col_types = FALSE) |&gt;
  mutate(text_marked = coalesce(text_marked, ""),
         tier_short = str_sub(tier, 1, 1))

empty_corr &lt;- tibble(page_id = character(), status = character(),
                     corrected_text = character(), saved_at = character())

read_corr &lt;- function() {
  if (!file.exists(corr_path)) return(empty_corr)
  read_csv(corr_path, col_types = "cccc", show_col_types = FALSE)
}

write_corr &lt;- function(x) {
  # Write then rename so a crash cannot leave a half-written file
  tmp &lt;- paste0(corr_path, ".tmp")
  write_csv(x, tmp)
  file.rename(tmp, corr_path)
}

# Warn the browser before closing the tab while there are unsaved edits
dirty_js &lt;- "
Shiny.addCustomMessageHandler('dirty', function(isDirty) {
  window.onbeforeunload = isDirty ? function(e) { e.preventDefault(); e.returnValue = ''; return ''; } : null;
});"

ui &lt;- page_sidebar(
  title = "Pomeroy journals: proofreading",
  tags$head(tags$script(HTML(dirty_js))),
  sidebar = sidebar(
    width = 300,
    checkboxGroupInput("tiers", "Tier",
      c("A: manual typing" = "A", "B: proofread" = "B", "C: spot check" = "C"),
      selected = c("A", "B")),
    checkboxGroupInput("vols", "Volume",
      sort(unique(pages$volume)), selected = sort(unique(pages$volume)), inline = TRUE),
    radioButtons("status", "Status", c("All" = "all", "To do" = "todo", "Done" = "done"),
                 inline = TRUE),
    selectInput("page", "Page", choices = NULL),
    layout_columns(
      actionButton("prev", "Previous"),
      actionButton("nxt", "Next")
    ),
    hr(),
    radioButtons("img_type", "Image",
      c("Flagged words boxed (half size)" = "review", "Clean (full resolution)" = "scan")),
    sliderInput("zoom", "Zoom (%)", 50, 250, 100, step = 10),
    hr(),
    textOutput("progress")
  ),
  layout_columns(
    col_widths = c(6, 6),
    card(card_header(textOutput("img_title")), full_screen = TRUE,
         div(style = "overflow:auto; height:78vh;", uiOutput("scan_img"))),
    card(card_header("Text", uiOutput("dirty_badge", inline = TRUE)),
         textAreaInput("txt", NULL, value = "", width = "100%", rows = 28),
         tags$style("#txt {font-family: monospace; font-size: 15px;}"),
         layout_columns(
           actionButton("save", "Save", class = "btn-primary"),
           actionButton("save_next", "Save and next", class = "btn-success"),
           actionButton("reset", "Reset to OCR draft")
         ),
         textOutput("msg"))
  )
)

server &lt;- function(input, output, session) {
  corr &lt;- reactiveVal(read_corr())
  current &lt;- reactiveVal(NULL)
  # Text as last loaded or saved; differs from the box when there are unsaved edits
  loaded &lt;- reactiveVal("")

  draft_for &lt;- function(id) pages$text_marked[pages$page_id == id]

  visible &lt;- reactive({
    done_ids &lt;- corr()$page_id
    keep &lt;- pages |&gt;
      filter(tier_short %in% input$tiers, volume %in% input$vols)
    if (input$status == "todo") keep &lt;- filter(keep, !page_id %in% done_ids)
    if (input$status == "done") keep &lt;- filter(keep, page_id %in% done_ids)
    keep
  })

  is_dirty &lt;- reactive(!is.null(current()) && !identical(input$txt, loaded()))

  # Save text for a given page and record it as the new baseline if it is the open page
  save_page &lt;- function(id, text, note = "Saved") {
    new &lt;- tibble(page_id = id,
                  status = if (identical(text, draft_for(id))) "confirmed" else "edited",
                  corrected_text = text,
                  saved_at = format(Sys.time(), "%Y-%m-%d %H:%M:%S"))
    updated &lt;- isolate(corr()) |&gt; filter(page_id != id) |&gt; bind_rows(new) |&gt; arrange(page_id)
    write_corr(updated)
    corr(updated)
    output$msg &lt;- renderText(sprintf("%s %s (%s) at %s", note, id, new$status, new$saved_at))
  }

  # Keep the page dropdown in sync with filters and the current page
  observe({
    v &lt;- visible()
    done_ids &lt;- corr()$page_id
    lab &lt;- sprintf("%s p%d [%s]%s", v$volume, v$page, v$tier_short,
                   if_else(v$page_id %in% done_ids, " done", ""))
    sel &lt;- isolate(current())
    if (is.null(sel) || !sel %in% v$page_id) sel &lt;- v$page_id[1]
    updateSelectInput(session, "page", choices = setNames(v$page_id, lab), selected = sel)
  })

  # Leaving a page with unsaved edits saves them first
  observeEvent(input$page, {
    req(input$page)
    old &lt;- current()
    if (!is.null(old) && old != input$page && !identical(input$txt, loaded())) {
      save_page(old, input$txt, note = "Auto-saved")
    }
    current(input$page)
    saved &lt;- filter(corr(), page_id == input$page)
    start &lt;- if (nrow(saved)) saved$corrected_text[1] else draft_for(input$page)
    loaded(start)
    updateTextAreaInput(session, "txt", value = start)
  })

  step &lt;- function(by) {
    ids &lt;- visible()$page_id
    i &lt;- match(current(), ids)
    if (!is.na(i) && i + by &gt;= 1 && i + by &lt;= length(ids)) {
      updateSelectInput(session, "page", selected = ids[i + by])
    }
  }
  observeEvent(input$prev, step(-1))
  observeEvent(input$nxt, step(1))

  observeEvent(input$save, {
    req(current())
    save_page(current(), input$txt)
    loaded(input$txt)
  })

  observeEvent(input$save_next, {
    req(current())
    ids &lt;- visible()$page_id
    i &lt;- match(current(), ids)
    save_page(current(), input$txt)
    loaded(input$txt)
    if (!is.na(i) && i &lt; length(ids)) updateSelectInput(session, "page", selected = ids[i + 1])
  })

  observeEvent(input$reset, {
    updateTextAreaInput(session, "txt", value = draft_for(current()))
  })

  observe(session$sendCustomMessage("dirty", isTRUE(is_dirty())))

  output$dirty_badge &lt;- renderUI({
    if (isTRUE(is_dirty())) {
      span(class = "badge text-bg-warning ms-2", "Unsaved changes (saved automatically when you change page)")
    } else {
      span(class = "badge text-bg-secondary ms-2", "No unsaved changes")
    }
  })

  output$img_title &lt;- renderText({
    req(current())
    r &lt;- pages[pages$page_id == current(), ]
    sprintf("%s, page %d | tier %s | mean confidence %.0f%% | %s",
            r$volume, r$page, r$tier_short, r$mean_conf, coalesce(r$reason, "no flag"))
  })

  output$scan_img &lt;- renderUI({
    req(current())
    use_review &lt;- input$img_type == "review" &&
      file.exists(file.path(root, "data", "pages", "review", paste0(current(), ".png")))
    src &lt;- sprintf("%s/%s.png", if (use_review) "review" else "scan", current())
    # Fixed display width regardless of file size, so zoom behaves the same for both
    tags$img(src = src, style = sprintf("width:%dpx; max-width:none;", round(10 * input$zoom)))
  })

  output$progress &lt;- renderText({
    v &lt;- pages |&gt; filter(tier_short %in% c("A", "B"))
    sprintf("Tier A/B pages saved: %d of %d", sum(corr()$page_id %in% v$page_id), nrow(v))
  })
}

shinyApp(ui, server)
